# Definición tipada y testeable en código (patrón BAML / Pydantic)
class ExtractInput(BaseModel):
    raw_email: str

def build_extract_prompt(data: ExtractInput) -> list[dict]:
    return [{"role": "system", "content": "Extrae remitente y urgencia en JSON."},
            {"role": "user", "content": f"<email>{data.raw_email}</email>"}]

