Prompt evaluation.ejemplo:
def evaluate_prompt(prompt_fn, dataset):
    passed = 0
    for case in dataset:
        out = prompt_fn(case["input"])
        if is_valid_json(out) and llm_judge(out, case["rubric"]) >= 4:
            passed += 1
    return passed / len(dataset)
